// Generated by Suite Builder from a crawl of the site. The suite's audit command: which of the audit's items are fixed, and the record (node menu/audit.mjs).
// EDIT RULES: do not edit this file; regenerating replaces all of it. The menu is menu/menu.mjs; your own commands go in a file of your own.
// Creator: https://github.com/ghost-in-the-kernel
// The suite's audit command. It shows which items of the site's audit the last audit run saw fixed, and keeps the
// record. Plain Node. It starts only git (to name the suite's commit and who ran it), never Suite Builder.
//   node menu/audit.mjs status            each item as the last run saw it; writes audit/STATUS.md
//   node menu/audit.mjs baseline          keeps the last run as the before: audit/runs/baseline-<stamp>.md
//   node menu/audit.mjs accept [ids]      accepts the items the last run saw FIXED (no ids: the firm ones only)
//   node menu/audit.mjs dismiss <id> --why "..."   marks one a false finding or an accepted risk
// --other-address: use a run made against another address than the audited one (staging, say). The record says so.
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readdirSync, readFileSync, unlinkSync, writeFileSync } from 'node:fs';
import { userInfo } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
/** The site the audit read, and where the audit family writes its run's result. */
const ORIGIN = "https://leotechnologies.com";
const RUN = "target/audit/run.json";
const FORMAT = "suite-audit-run/1";
const OPEN_DIR = 'bugs/open';
const FIXED = 'bugs/FIXED.md';
const SEEN = 'audit/seen-open.json';
const STATUS = 'audit/STATUS.md';
/** The first line of a bug the system filed: only those are the suite's to change. */
const MARK = '<!-- Filed by Suite Builder: a system bug.';
/** What a bug filed for its audit items alone says it blocks: it goes with its last item. */
// Its own line, never the site's words: a page that says it would make a blocking bug look audit-only.
const AUDIT_ONLY = /^\*\*What it blocks:\*\* No test of the regular run trips on it/m;
const ITEM = /^- `(SITE-\d+-[0-9a-f]{8})` /;
const ACCEPTED = /^- (\d{4}-\d{2}-\d{2}) {2}`(SITE-\d+-[0-9a-f]{8})` (.*?): fixed, accepted by (.*)$/d;
const NOT_FOUND = /^- (\d{4}-\d{2}-\d{2}) {2}`(SITE-\d+-[0-9a-f]{8})` (.*?): not found by the crawl of (\S+)/d;
const DISMISSED = /; dismissed (\d{4}-\d{2}-\d{2}) by (.*)$/d;
const USAGE = `node menu/audit.mjs status | baseline | accept [ids] | dismiss <id> --why "..."
  status      each item as the last audit run saw it; writes ${STATUS}
  baseline    keeps the last run as the before (audit/runs/baseline-<stamp>.md)
  accept [ids]  accepts the items the last run saw FIXED: with no ids, the firm ones only
  dismiss <id> --why "..."   a false finding or an accepted risk: it leaves the count, kept with who, when and why
  --other-address   take a run made against another address than ${ORIGIN} (it is recorded so)`;

const path = (p) => join(ROOT, p);
const read = (p) => (existsSync(path(p)) ? readFileSync(path(p), 'utf8') : '');
function write(p, text) {
  mkdirSync(dirname(path(p)), { recursive: true });
  writeFileSync(path(p), text);
}
function stop(words) {
  console.log(words);
  process.exit(1);
}
const today = () => new Date().toISOString().slice(0, 10);
/** Text with no control or format character: nothing that moves a terminal, flips text or hides in a file. */
const clean = (text) => String(text).replace(/[\p{Cc}\p{Cf}\p{Zl}\p{Zp}]/gu, ' ');
/**
 * A line's own words. Each quoted span of the site's words (a key, a title's words, in backticks) is blanked to the
 * same number of NULs. So a page whose title says "; dismissed" or ": fixed, accepted by " never reads as the ledger
 * saying it. The line's markers are looked for here, at the place they hold in the line.
 */
const ownWords = (line) => line.replace(/(`+)[\s\S]*?\1/g, (span) => '\0'.repeat(span.length));
/** An item's key as its line says it: a quoted one (the site's own words, in backticks) whole, else up to the first ": ". */
const keyOf = (line) => {
  const rest = line.replace(ITEM, '');
  const end = ownWords(rest).indexOf(': ');
  return end < 0 ? rest : rest.slice(0, end);
};
/** A key as the site said it: a quoted one (a ledger line's) unquoted, its cell's escaped pipes undone; any other as it is. */
const rawKey = (key) => {
  const q = /^(`+)( ?)([\s\S]*?)\2\1$/.exec(key);
  return q && !q[3].includes(q[1]) ? q[3].replace(/\\\|/g, '|') : key;
};
/**
 * A key or the site's words, for a table cell. Anything but a plain address is quoted as the site's words (in
 * backticks). A pipe is escaped.
 */
const PLAIN = /^[\w/.:?=&%~+@,;#-]*$/;
function quoted(text) {
  const words = clean(text).replace(/\s+/g, ' ').trim().replace(/\|/g, '\\|');
  const fence = '`'.repeat(Math.max(0, ...(words.match(/`+/g) ?? []).map((run) => run.length)) + 1);
  return words ? `${fence}${/^`|`$/.test(words) ? ` ${words} ` : words}${fence}` : '` `';
}
const keyCell = (key) => (PLAIN.test(key) ? key : quoted(key));
const wordsCell = (words) => clean(words).replace(/\s+/g, ' ').replace(/\|/g, '\\|').replace(/</g, '&lt;');
/** Where what a check saw goes in an outcome's words for a cell: replaced by it quoted, as the site's words. */
const SAID = String.fromCharCode(0xe000);
/** An item's outcome in a table cell: the tool's words escaped, what the check saw (the site's words among them) quoted. */
const outcomeCell = (i, book, seen) => wordsCell(outcome({ ...i, said: SAID }, book, seen).words).replace(SAID, () => quoted(i.said));
const codeOf = (id) => id.slice(0, -9);

/** git's answer, or null when there is no git or no repository; git alone is started, with fixed arguments. */
function git(...args) {
  const r = spawnSync('git', args, { cwd: ROOT, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
  return r.status === 0 ? r.stdout.trim() || null : null;
}
/** Who ran it, as git says (anyone can set it: no signature is claimed). */
const who = () => {
  const name = git('config', 'user.name');
  return name ? `${name}, as git says` : `${userInfo().username} (the login name: git has no user.name)`;
};

/**
 * The ledger. It holds the open items of the system's bugs, by id, and the codes whose bug is a person's. It also holds
 * FIXED.md's accepted and closed items.
 */
function ledger() {
  const items = new Map();
  const persons = new Set();
  const files = existsSync(path(OPEN_DIR)) ? readdirSync(path(OPEN_DIR)).filter((f) => f.endsWith('.md')) : [];
  for (const f of files) {
    const file = `${OPEN_DIR}/${f}`;
    const text = read(file);
    if (!text.startsWith(MARK)) {
      persons.add(f.slice(0, -3));
      continue;
    }
    for (const line of text.split('\n')) {
      const m = ITEM.exec(line);
      if (!m) continue;
      // Each marker in the line's own words (ownWords), its words taken from the line at the same place.
      const own = m[0] + ownWords(line.slice(m[0].length));
      const d = DISMISSED.exec(own);
      items.set(m[1], { id: m[1], key: keyOf(line), line, file, since: /\((?:since|found again by the crawl of) (\d{4}-\d{2}-\d{2})/.exec(own)?.[1] ?? '', reopened: own.includes('(found again by the crawl of'), dismissed: d ? `dismissed ${d[1]} by ${line.slice(d.indices[2][0])}` : null });
    }
  }
  const accepted = new Map();
  const closed = new Map();
  for (const line of read(FIXED).split('\n')) {
    const start = /^- \d{4}-\d{2}-\d{2} {2}`SITE-\d+-[0-9a-f]{8}` /.exec(line)?.[0] ?? '';
    const own = start + ownWords(line.slice(start.length));
    const at = (m, n) => line.slice(...m.indices[n]);
    const a = ACCEPTED.exec(own);
    if (a) accepted.set(a[2], { date: a[1], key: at(a, 3), by: at(a, 4) });
    const c = NOT_FOUND.exec(own);
    if (c) closed.set(c[2], { date: c[1], key: at(c, 3) });
  }
  return { items, persons, accepted, closed };
}

/** The last run's result, as the audit family wrote it; null when there is none. */
function lastRun() {
  if (!existsSync(path(RUN))) return null;
  const run = JSON.parse(read(RUN));
  if (run.format !== FORMAT) stop(`${RUN} is a run of another format (${run.format}): this suite reads ${FORMAT}. Run the audit tests again.`);
  return run;
}
const needRun = () => lastRun() ?? stop(`No audit run yet (${RUN}): run the audit tests first, then this again.\n${USAGE}`);

/** A run against another address than the audited one is refused unless asked for. Either way, its address is kept. */
function againstSaid(run, told) {
  const base = new URL(run.base).origin;
  if (base === new URL(ORIGIN).origin) return run.base;
  if (!told) stop(`This run ran against ${run.base}, not the audited origin ${ORIGIN}: what it saw is not the site the audit read.\nTo take it all the same (and record so): node menu/audit.mjs ${process.argv.slice(2).join(' ')} --other-address`);
  return `${run.base} (not the audited origin: told so with --other-address)`;
}

/** The items the suite has seen open, with the first run that did: a pass counts as FIXED only for one of them. */
function sightings(run) {
  const seen = existsSync(path(SEEN)) ? JSON.parse(read(SEEN)) : {};
  let added = false;
  for (const i of run?.items ?? []) {
    if (i.seen === 'open' && !seen[i.id]) {
      seen[i.id] = run.finished;
      added = true;
    }
  }
  if (added) write(SEEN, `${JSON.stringify(seen, null, 2)}\n`);
  return seen;
}

/** One item's outcome: what the run saw, against what the ledger expects. */
function outcome(i, book, seen) {
  const open = book.items.get(i.id);
  if (open?.dismissed) return { state: 'dismissed', words: `${open.dismissed}` };
  if (i.seen === 'cannot') return { state: 'cannot', words: `could not check: ${i.said}` };
  const accepted = !open && book.accepted.get(i.id);
  if (accepted) return i.seen === 'fixed' ? { state: 'accepted', words: `fixed, accepted ${accepted.date}` } : { state: 'reopened', words: `REOPENED: accepted fixed on ${accepted.date}, ${i.said} again` };
  if (i.seen === 'open') return { state: 'open', words: `expected: still open (${i.said})` };
  if (!seen[i.id]) return { state: 'not-reproduced', words: `NOT REPRODUCED (${i.said}): the suite never saw it open, so this is no fix; a baseline run that sees it open counts, or node menu/audit.mjs dismiss ${i.id} --why "..."` };
  return { state: 'fixed', words: `FIXED (${i.said})${i.firm ? '' : ', a softer check: confirm by eye'}: not yet accepted; node menu/audit.mjs accept ${i.id}` };
}

/** The run's last lines: how many items were seen fixed, of how many, and the findings no test checks. */
function lastLines(run, outcomes) {
  const counted = outcomes.filter((o) => o.state !== 'dismissed');
  const fixed = counted.filter((o) => o.state === 'fixed' || o.state === 'accepted').length;
  const dismissed = outcomes.length - counted.length;
  const unchecked = run.unchecked ?? [];
  return [
    ...(unchecked.length ? [`${unchecked.length} finding${unchecked.length === 1 ? ' of the audit is' : 's of the audit are'} checked by no test: ${unchecked.map((u) => u.code).join(', ')}.`] : []),
    `${fixed} of ${counted.length} audit items fixed since the audit of ${run.of}${dismissed ? ` (${dismissed} dismissed)` : ''}.`,
  ];
}

/** The record's head: when, the suite's commit, the audited origin, the address run against, who, and which tests. */
function record(run, against) {
  const tests = (run.items ?? []).map((i) => `${i.id} ${i.check}`).sort().join('\n');
  return [
    `Recorded: ${new Date().toISOString().slice(0, 16).replace('T', ' ')} UTC`,
    `The suite's commit: ${git('rev-parse', 'HEAD') ?? 'none (not a git repository, or nothing committed)'}`,
    `Audited origin: ${ORIGIN}`,
    `Run against: ${against}`,
    `By: ${who()}`,
    `Audit tests' fingerprint: ${createHash('sha256').update(tests).digest('hex').slice(0, 16)}`,
    `The audit of: ${run.of}; the run: ${run.started} to ${run.finished} (${run.framework}${run.browser ? `, ${run.browser}` : ''})`,
  ];
}

/** A run kept: its record, one row per item, its last lines; never written over. */
function keep(run, against, book, seen, name, more = []) {
  const stamp = run.finished.slice(0, 16).replace('T', '-').replace(':', '');
  let file = `audit/runs/${name}${stamp}.md`;
  for (let n = 2; existsSync(path(file)); n++) file = `audit/runs/${name}${stamp}-${n}.md`;
  const outcomes = run.items.map((i) => outcome(i, book, seen));
  // A key from the run is the site's own words as they are: quoted unless a plain address, whatever it starts with.
  const rows = run.items.map((i) => `| \`${i.id}\` | ${keyCell(i.key)} | ${outcomeCell(i, book, seen)} |`);
  write(file, [`# Audit run of ${run.finished.slice(0, 16).replace('T', ' ')} UTC`, '', ...record(run, against), ...more, '', '| Item | What | This run |', '| --- | --- | --- |', ...rows, '', ...lastLines(run, outcomes), ''].join('\n'));
  return file;
}

/** audit/STATUS.md: every item the ledger has held, its state, and what the last run saw of it. */
function status(run, book, seen) {
  const last = new Map((run?.items ?? []).map((i) => [i.id, outcomeCell(i, book, seen)]));
  const ids = [...new Set([...book.items.keys(), ...book.accepted.keys(), ...book.closed.keys()])].sort();
  const state = (id) => {
    const open = book.items.get(id);
    if (open?.dismissed) return open.dismissed;
    if (open) return open.reopened ? `open again since ${open.since}` : `open since ${open.since}`;
    const a = book.accepted.get(id);
    if (a) return `fixed, accepted ${a.date} by ${a.by}`;
    return `not found by the crawl of ${book.closed.get(id).date}`;
  };
  // A key as the ledger's line has it (quoted there when the site's words), taken back to the site's words and quoted once.
  const key = (id) => rawKey(book.items.get(id)?.key ?? book.accepted.get(id)?.key ?? book.closed.get(id)?.key ?? '');
  const rows = ids.map((id) => `| \`${id}\` | ${keyCell(key(id))} | ${wordsCell(state(id))} | ${last.get(id) ?? (run ? 'not in the last run' : 'no run yet')} |`);
  const outcomes = (run?.items ?? []).map((i) => outcome(i, book, seen));
  const text = [
    '# The audit: what was open, what is fixed, when, by which run',
    '',
    `Written by node menu/audit.mjs from bugs/ and the last audit run (${RUN}); audit/runs/ keeps each run accepted or taken as the before. An item is fixed when the owner's own run of the audit tests against the live address says so.`,
    '',
    ...(run ? record(run, run.base) : [`Audited origin: ${ORIGIN}`, 'No audit run yet.']),
    '',
    '| Item | What | State | The last run |',
    '| --- | --- | --- | --- |',
    ...rows,
    '',
    ...(run ? lastLines(run, outcomes) : []),
    '',
  ].join('\n');
  write(STATUS, text);
  return { text, outcomes };
}

/** Accept: each item the last run saw FIXED leaves bugs/open/ and joins bugs/FIXED.md; the run is kept. */
function accept(ids, told) {
  const run = needRun();
  const against = againstSaid(run, told);
  const seen = sightings(run);
  const book = ledger();
  const outcomes = run.items.map((i) => outcome(i, book, seen));
  const of = new Map(run.items.map((i, n) => [i.id, { i, o: outcomes[n] }]));
  const take = ids.length ? ids : run.items.filter((i, n) => i.firm && outcomes[n].state === 'fixed').map((i) => i.id);
  const refused = [];
  for (const id of take) {
    if (book.persons.has(codeOf(id))) refused.push(`${id}: ${OPEN_DIR}/${codeOf(id)}.md is a person's: its items are not the suite's to accept.`);
    else if (!of.has(id) || !book.items.has(id)) refused.push(`${id}: not an item of this suite open in its ledger, nor in the last run.`);
    else if (of.get(id).o.state !== 'fixed') refused.push(`${id}: ${clean(of.get(id).o.words)}`);
  }
  if (refused.length) stop(`Nothing accepted:\n${refused.map((r) => `  ${r}`).join('\n')}`);
  if (!take.length) {
    console.log('Nothing to accept: the last run saw no firm item FIXED. A softer one is accepted by its id.');
    return;
  }
  const report = keep(run, against, book, seen, '', [`Accepted: ${take.map((id) => `\`${id}\``).join(', ')}`]);
  const fixed = [];
  const byFile = new Map();
  for (const id of take) byFile.set(book.items.get(id).file, [...(byFile.get(book.items.get(id).file) ?? []), id]);
  for (const [file, gone] of byFile) {
    const text = read(file);
    const lines = text.split('\n').filter((l) => !gone.includes(ITEM.exec(l)?.[1]));
    for (const id of gone) fixed.push(`- ${today()}  \`${id}\` ${book.items.get(id).key}: fixed, accepted by ${who()} (${report})`);
    if (AUDIT_ONLY.test(text) && !lines.some((l) => ITEM.test(l))) {
      unlinkSync(path(file));
      fixed.push(`- ${today()}  ${/^# (.*)$/m.exec(text)?.[1] ?? file}: fixed, its last item accepted (filed ${/^Filed from the crawl of (\S+?),/m.exec(text)?.[1] ?? 'earlier'})`);
    } else write(file, lines.join('\n'));
  }
  const before = read(FIXED) || '# Fixed bugs\n\nOne line for each bug closed as fixed: the date, the bug, and what showed it fixed.\n\n';
  write(FIXED, `${before.endsWith('\n') ? before : `${before}\n`}${fixed.join('\n')}\n`);
  status(run, ledger(), seen);
  console.log(`Accepted ${take.length} item${take.length === 1 ? '' : 's'}: ${take.join(', ')}.\nThe run is kept as ${report}; ${FIXED} and ${STATUS} say it. Commit them: the record is a file in git.`);
}

/** Dismiss: one item marked a false finding or an accepted risk, with who, when and why; it leaves the count. */
function dismiss(id, why) {
  if (!id) stop(USAGE);
  const book = ledger();
  if (book.persons.has(codeOf(id))) stop(`${id}: ${OPEN_DIR}/${codeOf(id)}.md is a person's: its items are not the suite's to dismiss.`);
  const open = book.items.get(id);
  if (!open) stop(`${id} is not an item of this suite open in its ledger (${OPEN_DIR}/).`);
  if (open.dismissed) stop(`${id} is already ${open.dismissed}.`);
  if (!why) stop(`Say why: node menu/audit.mjs dismiss ${id} --why "a false finding: ..." (or an accepted risk).`);
  const text = read(open.file);
  write(open.file, text.split('\n').map((l) => (l === open.line ? `${l}; dismissed ${today()} by ${who()}: ${why.replace(/\s+/g, ' ')}` : l)).join('\n'));
  const run = lastRun();
  status(run, ledger(), sightings(run));
  console.log(`Dismissed ${id}: it leaves the count, and ${STATUS} keeps it with who, when and why.`);
}

const args = process.argv.slice(2);
const told = args.includes('--other-address');
const whyAt = args.indexOf('--why');
const why = whyAt >= 0 ? (args[whyAt + 1] ?? '').trim() : '';
const words = args.filter((a, n) => !a.startsWith('--') && !(whyAt >= 0 && n === whyAt + 1));
const [command, ...rest] = words;
if (command === 'status') {
  const run = needRun();
  const { outcomes } = status(run, ledger(), sightings(run));
  if (new URL(run.base).origin !== new URL(ORIGIN).origin) console.log(`This run ran against ${run.base}, not the audited origin ${ORIGIN}.`);
  for (const [n, i] of run.items.entries()) console.log(`  ${i.id}: ${clean(outcomes[n].words)}`);
  for (const line of lastLines(run, outcomes)) console.log(line);
  console.log(`Written: ${STATUS}`);
} else if (command === 'baseline') {
  const run = needRun();
  const against = againstSaid(run, told);
  const seen = sightings(run);
  const book = ledger();
  const outcomes = run.items.map((i) => outcome(i, book, seen));
  const file = keep(run, against, book, seen, 'baseline-');
  status(run, book, seen);
  console.log(`The before is kept: ${file} (${outcomes.filter((o) => o.state === 'open').length} of ${run.items.length} items seen open). ${STATUS} written.`);
} else if (command === 'accept') accept(rest, told);
else if (command === 'dismiss') dismiss(rest[0], why);
else stop(USAGE);
